package com.lightweight.snake

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool

/**
 * Thin SoundPool wrapper for the two tiny synthesized WAVs in res/raw
 * (generated by tools/gen_sounds.py). Call release() from surfaceDestroyed.
 */
class Sound(ctx: Context) {

    private val pool = SoundPool.Builder()
        .setMaxStreams(4)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()

    private val eatId = pool.load(ctx, R.raw.s_eat, 1)
    private val overId = pool.load(ctx, R.raw.s_over, 1)

    fun eat() { pool.play(eatId, 0.7f, 0.7f, 1, 0, 1f) }
    fun over() { pool.play(overId, 0.85f, 0.85f, 1, 0, 1f) }

    fun release() { pool.release() }
}
